standard_solution_code:
from typing import List

class Solution:

	def findMaxSubsetSum(self, N: int, A: List[int]) -> int:
		(prev, curr) = ([0, A[0]], [0, 0])
		for i in range(1, N):
			(curr[0], curr[1], prev) = (prev[1], A[i] + max(prev), curr)
		return max(prev)
